import Foundation

/// ClaudeBar's cat sounds (generated by scripts/make-sounds.py; no recorded audio).
public enum CatSound: String, Sendable, CaseIterable { case meow, purr, ding }

/// What happened: a cat started needing you, finished its work, was clicked, or stepped out of the elevator.
public enum SoundEvent: Equatable, Sendable {
    case needsYou(String)
    case finished(String)
    case clicked
    case elevator
}

/// Which sounds are on, and how loud (0…1). In projects.json under "sounds".
public struct SoundSettings: Equatable, Sendable {
    public var needsYou: Bool
    public var finished: Bool
    public var click: Bool
    public var elevator: Bool
    public var volume: Double
    /// The office's lofi loop (the 🎵 button).
    public var music: Bool
    /// Settings' "Cat sounds" switch: off silences every cat sound (not the music), keeping each sound's own switch.
    public var on: Bool

    public init(needsYou: Bool = true, finished: Bool = true, click: Bool = true, elevator: Bool = false, volume: Double = 0.6,
                music: Bool = true, on: Bool = true) {
        self.needsYou = needsYou
        self.finished = finished
        self.click = click
        self.elevator = elevator
        self.volume = volume
        self.music = music
        self.on = on
    }

    /// How many of the four cat sounds are switched on ("Choose sounds · 3 of 4 on").
    public var chosenCount: Int { [needsYou, finished, click, elevator].filter { $0 }.count }
    public static let chosenTotal = 4
}

/// Decides whether an event makes a sound: its switch is on, nothing played in the last 3 s, and (for the alerts)
/// the same cat didn't make the same alert in the last minute.
public struct SoundGate: Sendable {
    public static let spacing: TimeInterval = 3
    public static let repeatAfter: TimeInterval = 60
    private var last: Date?
    private var lastAlert: [String: Date] = [:]

    public init() {}

    public mutating func sound(for event: SoundEvent, settings: SoundSettings, now: Date) -> CatSound? {
        let (sound, on, alertKey): (CatSound, Bool, String?) = switch event {
        case .needsYou(let k): (.meow, settings.needsYou, "needsYou|\(k)")
        case .finished(let k): (.purr, settings.finished, "finished|\(k)")
        case .clicked: (.meow, settings.click, nil)
        case .elevator: (.ding, settings.elevator, nil)
        }
        guard on, settings.on else { return nil }
        if let last, now.timeIntervalSince(last) < Self.spacing { return nil }
        if let alertKey, let before = lastAlert[alertKey], now.timeIntervalSince(before) < Self.repeatAfter { return nil }
        last = now
        if let alertKey { lastAlert[alertKey] = now }
        return sound
    }
}
